using Clary.Api.Identity;
using System.Net;
using System.Text.Json;
using System.Text.Json.Serialization;
using Npgsql;
using NpgsqlTypes;
namespace Clary.Api;
[JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
public sealed record AssetInput(string? AssetTag,string? Computer,string? SerialNumber=null,string? IpAddress=null,string? Assignee=null,string? Department=null,string? Location=null,string Status="Available",int? Revision=null,string Category="Computer",string? CustomCategory=null,Guid? EmployeeId=null,Guid? DepartmentId=null,Guid? LocationId=null,string? NewAssigneeName=null,bool ClearEmployee=false,bool ClearDepartment=false,bool ClearLocation=false,Guid? AssetTypeId=null,IReadOnlyDictionary<string,JsonElement>? CustomFields=null);
public sealed record InventoryAsset(Guid Id,string AssetTag,string Computer,string? SerialNumber,string? IpAddress,string? Assignee,string? Department,string? Location,string Status,int Revision,DateTime UpdatedAt,string SoftwareStatus="Not checked",DateTime? LastSeen=null,string Category="Computer",string? CustomCategory=null,Guid? EmployeeId=null,Guid? DepartmentId=null,Guid? LocationId=null,Guid? AssetTypeId=null,string? AssetTypeName=null,IReadOnlyDictionary<string,JsonElement>? CustomFields=null);
public sealed record AssetActivity(Guid Id,Guid AssetId,string Computer,string Kind,DateTime CreatedAt);
public sealed class InventoryConflict(string message):Exception(message);
public sealed class InventoryMissing():Exception("This asset no longer exists.");
public sealed class InventoryRepository(NpgsqlDataSource db){
 static void Visibility(NpgsqlCommand q,CompanyContext context){q.Parameters.AddWithValue("employee",NpgsqlDbType.Uuid,(object?)(context.VisibilityScope==CompanyVisibilityScope.AssignedOnly?context.EmployeeId:null)??DBNull.Value);q.Parameters.AddWithValue("visible",context.VisibilityScope!=CompanyVisibilityScope.AssignedOnly||context.EmployeeId.HasValue);}
 const string Columns="a.id,a.asset_tag,a.computer,a.serial_number,a.ip_address,CASE WHEN a.employee_id IS NULL THEN a.assignee ELSE e.display_name END,CASE WHEN a.department_id IS NULL THEN a.department ELSE d.name END,CASE WHEN a.location_id IS NULL THEN a.location ELSE l.name END,a.status,a.revision,a.updated_at,a.category,a.custom_category,a.employee_id,a.department_id,a.location_id,a.asset_type_id,t.name,a.custom_fields::text";
 const string Joined="inventory_assets a LEFT JOIN asset_types t ON t.company_id=a.company_id AND t.id=a.asset_type_id LEFT JOIN employees e ON e.company_id=a.company_id AND e.id=a.employee_id LEFT JOIN inventory_departments d ON d.company_id=a.company_id AND d.id=a.department_id LEFT JOIN locations l ON l.company_id=a.company_id AND l.id=a.location_id";
 static InventoryAsset Read(NpgsqlDataReader r)=>new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.IsDBNull(3)?null:r.GetString(3),r.IsDBNull(4)?null:r.GetString(4),r.IsDBNull(5)?null:r.GetString(5),r.IsDBNull(6)?null:r.GetString(6),r.IsDBNull(7)?null:r.GetString(7),r.GetString(8),r.GetInt32(9),r.GetDateTime(10),Category:r.GetString(11),CustomCategory:r.IsDBNull(12)?null:r.GetString(12),EmployeeId:r.IsDBNull(13)?null:r.GetGuid(13),DepartmentId:r.IsDBNull(14)?null:r.GetGuid(14),LocationId:r.IsDBNull(15)?null:r.GetGuid(15),AssetTypeId:r.IsDBNull(16)?null:r.GetGuid(16),AssetTypeName:r.IsDBNull(17)?r.GetString(11):r.GetString(17),CustomFields:JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(r.GetString(18)));
 public async Task<IReadOnlyList<InventoryAsset>> ListAsync(CompanyContext context,CancellationToken ct){await using var q=CompanyCommand.Create(context,$"SELECT {Columns} FROM {Joined} WHERE a.company_id=@company AND (@employee IS NULL OR a.employee_id=@employee) AND @visible ORDER BY a.updated_at DESC,a.id",db);Visibility(q,context);await using var r=await q.ExecuteReaderAsync(ct);var rows=new List<InventoryAsset>();while(await r.ReadAsync(ct))rows.Add(Read(r));return rows;}
 public async Task<InventoryAsset?> GetAsync(CompanyContext context,Guid id,CancellationToken ct){await using var q=CompanyCommand.Create(context,$"SELECT {Columns} FROM {Joined} WHERE a.company_id=@company AND (@employee IS NULL OR a.employee_id=@employee) AND @visible AND a.id=@id",db);q.Parameters.AddWithValue("id",id);Visibility(q,context);await using var r=await q.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?Read(r):null;}
 public Task<InventoryAsset> CreateAsync(CompanyContext context,AssetInput input,CancellationToken ct)=>SaveAsync(context,Guid.NewGuid(),input,false,ct);
 public Task<InventoryAsset> UpdateAsync(CompanyContext context,Guid id,AssetInput input,CancellationToken ct)=>SaveAsync(context,id,input,true,ct);
 static string? Field(string? value,string label,int max=200,bool required=false){value=value?.Trim();if(string.IsNullOrEmpty(value)){if(required)throw new ArgumentException(label+" is required.");return null;}if(value.Length>max)throw new ArgumentException(label+" must be up to "+max+" characters.");return value;}
 async Task<InventoryAsset> SaveAsync(CompanyContext context,Guid id,AssetInput input,bool update,CancellationToken ct){
  await using var conn=await db.OpenConnectionAsync(ct);await using var tx=await conn.BeginTransactionAsync(ct);
  var result=await SaveWithinAsync(conn,tx,context,id,input,update,ct);await tx.CommitAsync(ct);return result;
 }
 // Brie shares this transaction with its receipt; normal UI calls keep documentation provisioning enabled.
 internal async Task<InventoryAsset> SaveWithinAsync(NpgsqlConnection conn,NpgsqlTransaction tx,CompanyContext context,Guid id,AssetInput input,bool update,CancellationToken ct,bool provisionDocumentation=true){

  var customCategory=Field(input.CustomCategory,"Category",100);var tag=Field(input.AssetTag,"Asset tag",100,true)!;var computer=Field(input.Computer,"Computer",100,true)!;var serial=Field(input.SerialNumber,"Serial number");var ip=Field(input.IpAddress,"IP address");if(ip is not null&&!IPAddress.TryParse(ip,out _))throw new ArgumentException("IP address must be a valid IPv4 or IPv6 address.");var person=input.Assignee;var department=input.Department;var location=input.Location;if(input.Status is not ("Available" or "Assigned" or "In repair" or "Retired"))throw new ArgumentException("Choose a valid asset status.");if(update&&input.Revision is not >0)throw new ArgumentException("Reload the asset before saving.");
  await AccountPermissions.RevalidateAsync(conn,tx,context,CompanyCapability.Write,ct);
  await using(var company=CompanyCommand.Create(context,"SELECT id FROM companies WHERE id=@company FOR UPDATE",conn,tx)){if(await company.ExecuteScalarAsync(ct) is null)throw new InventoryMissing();}
  InventoryAsset? before=null;
  if(update){await using var old=CompanyCommand.Create(context,$"SELECT {Columns} FROM {Joined} WHERE a.company_id=@company AND a.id=@id",conn,tx);old.Parameters.AddWithValue("id",id);await using var r=await old.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new InventoryMissing();before=Read(r);if(before.Revision!=input.Revision)throw new InventoryConflict("This asset was updated elsewhere. Reopen it before saving.");}
  var definitions=await AssetConfigurationRepository.Read(conn,tx,context,ct);
  var type=AssetFieldValidation.Resolve(definitions,input.AssetTypeId,input.Category,before?.AssetTypeId,before?.Category);
  var customFields=AssetFieldValidation.Merge(definitions,type.Id,input.CustomFields,before?.CustomFields);
  var customFieldsJson=JsonSerializer.Serialize(customFields);
  // Match the database CHECK, which measures PostgreSQL's canonical jsonb text.
  await using(var size=new NpgsqlCommand("SELECT octet_length(@values::jsonb::text)",conn,tx)){size.Parameters.AddWithValue("values",NpgsqlDbType.Jsonb,customFieldsJson);if(Convert.ToInt32(await size.ExecuteScalarAsync(ct))>65536)throw new ArgumentException("Custom field values must fit within 64KB.");}
  if(input.EmployeeId.HasValue&&input.NewAssigneeName is not null)throw new ArgumentException("Choose an employee or enter a new assignee, not both.");
  if((input.ClearEmployee&&(input.EmployeeId.HasValue||input.NewAssigneeName is not null||!string.IsNullOrWhiteSpace(input.Assignee)))||(input.ClearDepartment&&(input.DepartmentId.HasValue||!string.IsNullOrWhiteSpace(input.Department)))||(input.ClearLocation&&(input.LocationId.HasValue||!string.IsNullOrWhiteSpace(input.Location))))throw new ArgumentException("Clear cannot be combined with an assignment.");
  if((input.EmployeeId is null&&input.NewAssigneeName is null&&input.Assignee is not null&&input.Assignee!=before?.Assignee)||(input.DepartmentId is null&&input.Department is not null&&input.Department!=before?.Department)||(input.LocationId is null&&input.Location is not null&&input.Location!=before?.Location))throw new ArgumentException("Choose directory entries using their IDs or explicitly clear the selection.");
  var employeeId=input.ClearEmployee?null:input.EmployeeId??before?.EmployeeId;
  var departmentId=input.ClearDepartment?null:input.DepartmentId??before?.DepartmentId;
  var locationId=input.ClearLocation?null:input.LocationId??before?.LocationId;
  async Task<string?> Selection(string table,string name,Guid? selected,Guid? oldId,string? text,string? oldText,bool clear){
   if(clear)return null;
   if(selected is null){if(text is not null&&text!=oldText)throw new ArgumentException("Choose a directory entry using its ID.");return oldText;}
   await using var q=CompanyCommand.Create(context,$"SELECT {name},active FROM {table} WHERE company_id=@company AND id=@id",conn,tx);q.Parameters.AddWithValue("id",selected.Value);await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct)||(!r.GetBoolean(1)&&selected!=oldId))throw new ArgumentException("Choose an active directory entry in this company.");return r.GetString(0);
  }
  department=await Selection("inventory_departments","name",departmentId,before?.DepartmentId,input.Department,before?.Department,input.ClearDepartment);
  location=await Selection("locations","name",locationId,before?.LocationId,input.Location,before?.Location,input.ClearLocation);
  if(input.NewAssigneeName is not null){
   await AccountPermissions.RevalidateAsync(conn,tx,context,CompanyCapability.Settings,ct);
   var newName=Field(input.NewAssigneeName,"New assignee",100,true)!;
   await using(var duplicate=CompanyCommand.Create(context,"SELECT 1 FROM employees WHERE company_id=@company AND lower(btrim(display_name))=lower(@name)",conn,tx)){duplicate.Parameters.AddWithValue("name",newName);if(await duplicate.ExecuteScalarAsync(ct) is not null)throw new InventoryConflict("An employee with this name exists. Choose the existing employee explicitly.");}
   employeeId=Guid.NewGuid();
   await using(var create=CompanyCommand.Create(context,"INSERT INTO employees(id,company_id,display_name,department_id) VALUES(@id,@company,@name,@department)",conn,tx)){create.Parameters.AddWithValue("id",employeeId.Value);create.Parameters.AddWithValue("name",newName);create.Parameters.AddWithValue("department",NpgsqlDbType.Uuid,(object?)departmentId??DBNull.Value);await create.ExecuteNonQueryAsync(ct);}
   await AuditRepository.AppendAsync(conn,tx,context,"Created","employee",employeeId.Value,null,new {Id=employeeId,DisplayName=newName,DepartmentId=departmentId,Active=true,Revision=1},ct);
  }
  person=await Selection("employees","display_name",employeeId,before?.EmployeeId,input.NewAssigneeName is null?input.Assignee:null,before?.Assignee,input.ClearEmployee);
  var sql=update?"UPDATE inventory_assets SET asset_type_id=@assetTypeId,custom_fields=@customFields,custom_category=@customCategory,category=@category,asset_tag=@tag,normalized_tag=@normalized,computer=@computer,serial_number=@serial,ip_address=@ip,assignee=@person,department=@department,location=@location,employee_id=@employeeId,department_id=@departmentId,location_id=@locationId,status=@status,revision=revision+1,updated_at=now() WHERE company_id=@company AND id=@id AND revision=@revision":"INSERT INTO inventory_assets(company_id,id,asset_tag,normalized_tag,computer,serial_number,ip_address,assignee,department,location,status,category,custom_category,employee_id,department_id,location_id,asset_type_id,custom_fields) VALUES(@company,@id,@tag,@normalized,@computer,@serial,@ip,@person,@department,@location,@status,@category,@customCategory,@employeeId,@departmentId,@locationId,@assetTypeId,@customFields)";
  await using(var q=CompanyCommand.Create(context,sql,conn,tx)){q.Parameters.AddWithValue("id",id);q.Parameters.AddWithValue("tag",tag);q.Parameters.AddWithValue("normalized",tag.ToUpperInvariant());q.Parameters.AddWithValue("computer",computer);q.Parameters.AddWithValue("status",input.Status);q.Parameters.AddWithValue("category",type.Code);q.Parameters.AddWithValue("assetTypeId",type.Id);q.Parameters.AddWithValue("customFields",NpgsqlDbType.Jsonb,customFieldsJson);foreach(var (key,value) in new[]{("customCategory",customCategory),("serial",serial),("ip",ip),("person",person),("department",department),("location",location)})q.Parameters.AddWithValue(key,NpgsqlDbType.Text,(object?)value??DBNull.Value);foreach(var (key,value) in new[]{("employeeId",employeeId),("departmentId",departmentId),("locationId",locationId)})q.Parameters.AddWithValue(key,NpgsqlDbType.Uuid,(object?)value??DBNull.Value);if(update)q.Parameters.AddWithValue("revision",input.Revision!.Value);
   try{if(await q.ExecuteNonQueryAsync(ct)!=1)throw new InventoryConflict("This asset was updated elsewhere. Reopen it before saving.");}catch(PostgresException e)when(e.SqlState==PostgresErrorCodes.UniqueViolation){throw new InventoryConflict("An asset with this asset tag already exists.");}
  }
  InventoryAsset asset;
  await using(var q=CompanyCommand.Create(context,$"SELECT {Columns} FROM {Joined} WHERE a.company_id=@company AND a.id=@id",conn,tx)){q.Parameters.AddWithValue("id",id);await using var r=await q.ExecuteReaderAsync(ct);await r.ReadAsync(ct);asset=Read(r);}
  foreach(var (kind,resolved) in new[]{("employee",input.EmployeeId.HasValue||input.NewAssigneeName is not null||input.ClearEmployee),("department",input.DepartmentId.HasValue||input.ClearDepartment),("location",input.LocationId.HasValue||input.ClearLocation)})if(resolved){await using var q=CompanyCommand.Create(context,"DELETE FROM directory_mapping_review WHERE company_id=@company AND asset_id=@asset AND kind=@kind",conn,tx);q.Parameters.AddWithValue("asset",id);q.Parameters.AddWithValue("kind",kind);await q.ExecuteNonQueryAsync(ct);}
  await AuditRepository.AppendAsync(conn,tx,context,update?"Updated":"Created","asset",id,before,asset,ct);
  await using(var q=CompanyCommand.Create(context,"INSERT INTO inventory_activity(company_id,id,asset_id,computer,kind) VALUES(@company,@id,@asset,@computer,@kind)",conn,tx)){q.Parameters.AddWithValue("id",Guid.NewGuid());q.Parameters.AddWithValue("asset",id);q.Parameters.AddWithValue("computer",computer);q.Parameters.AddWithValue("kind",update?"Updated":"Added");await q.ExecuteNonQueryAsync(ct);}if(provisionDocumentation)await InventoryDocumentation.EnsureAsync(context,conn,tx,type.Code,ct);return asset;
 }
 public async Task<IReadOnlyList<AssetActivity>> ActivityAsync(CompanyContext context,int limit,CancellationToken ct){await using var q=CompanyCommand.Create(context,"SELECT id,asset_id,computer,kind,created_at FROM inventory_activity WHERE company_id=@company AND asset_id IN (SELECT id FROM inventory_assets WHERE company_id=@company AND (@employee IS NULL OR employee_id=@employee) AND @visible) ORDER BY created_at DESC,id LIMIT @limit",db);q.Parameters.AddWithValue("limit",Math.Clamp(limit,1,50));Visibility(q,context);await using var r=await q.ExecuteReaderAsync(ct);var rows=new List<AssetActivity>();while(await r.ReadAsync(ct))rows.Add(new(r.GetGuid(0),r.GetGuid(1),r.GetString(2),r.GetString(3),r.GetDateTime(4)));return rows;}
}

